import { parseCommandLine } from './lib/cli/argv.mjs';
import { dumpYamlDocument, parseYamlDocument } from './lib/yaml/index.mjs';

const command = parseCommandLine(process.argv.slice(2), process.argv[1]);

if (command.kind === 'help') {
  process.stdout.write(command.text);
  process.exit(0);
}

if (command.kind === 'error') {
  process.stderr.write(command.text);
  process.exit(command.exitCode);
}

try {
  const node = parseYamlDocument(command.args.a);
  const result = dumpYamlDocument(node);
  console.log(result);
} catch (error) {
  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
  process.exit(1);
}

