export class ScalarNode {
  constructor(kind, value) {
    this.type = 'scalar';
    this.kind = kind;
    this.value = value;
  }
}

export class SequenceNode {
  constructor(items = []) {
    this.type = 'sequence';
    this.items = items;
  }
}

export class MappingNode {
  constructor(entries = []) {
    this.type = 'mapping';
    this.entries = entries;
  }
}

export function scalar(kind, value) {
  return new ScalarNode(kind, value);
}

export function sequence(items = []) {
  return new SequenceNode(items);
}

export function mapping(entries = []) {
  return new MappingNode(entries);
}

export function cloneNode(node) {
  if (node.type === 'scalar') {
    return scalar(node.kind, node.value);
  }

  if (node.type === 'sequence') {
    const items = [];
    for (const item of node.items) {
      items.push(cloneNode(item));
    }
    return sequence(items);
  }

  const entries = [];
  for (const [key, value] of node.entries) {
    entries.push([cloneNode(key), cloneNode(value)]);
  }
  return mapping(entries);
}

