function basename(pathname) {
  if (!pathname) {
    return 'test4.mjs';
  }

  let lastSlash = pathname.length - 1;
  while (lastSlash >= 0) {
    const character = pathname[lastSlash];
    if (character === '/' || character === '\\') {
      return pathname.slice(lastSlash + 1) || 'test4.mjs';
    }
    lastSlash -= 1;
  }

  return pathname;
}

function isDigit(character) {
  return character >= '0' && character <= '9';
}

function isNegativeNumberToken(token) {
  if (!token || token.length < 2 || token[0] !== '-') {
    return false;
  }

  let index = 1;
  let sawDigit = false;
  let sawDot = false;

  if (token[index] === '.') {
    sawDot = true;
    index += 1;
  }

  while (index < token.length) {
    const character = token[index];
    if (isDigit(character)) {
      sawDigit = true;
      index += 1;
      continue;
    }

    if (character === '.' && !sawDot) {
      sawDot = true;
      index += 1;
      continue;
    }

    return false;
  }

  return sawDigit;
}

function looksLikeOption(token) {
  if (!token || token.length === 0) {
    return false;
  }

  if (token === '-') {
    return false;
  }

  if (token === '--') {
    return true;
  }

  if (isNegativeNumberToken(token)) {
    return false;
  }

  return token[0] === '-';
}

function usage(programName) {
  return `usage: ${programName} [-h] --a A\n`;
}

export function formatHelp(scriptPath) {
  const programName = basename(scriptPath);
  return `${usage(programName)}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;
}

export function formatError(scriptPath, message) {
  const programName = basename(scriptPath);
  return `${usage(programName)}${programName}: error: ${message}\n`;
}

export function parseCommandLine(argv, scriptPath) {
  let argumentValue = null;
  let sawA = false;
  const extras = [];
  let helpRequested = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      helpRequested = true;
      continue;
    }

    if (token === '--a') {
      const value = argv[index + 1];
      if (value === undefined || looksLikeOption(value)) {
        return {
          kind: 'error',
          text: formatError(scriptPath, 'argument --a: expected one argument'),
          exitCode: 2,
        };
      }

      sawA = true;
      argumentValue = value;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      sawA = true;
      argumentValue = token.slice(4);
      continue;
    }

    extras.push(token);
  }

  if (helpRequested) {
    return {
      kind: 'help',
      text: formatHelp(scriptPath),
      exitCode: 0,
    };
  }

  if (!sawA) {
    return {
      kind: 'error',
      text: formatError(scriptPath, 'the following arguments are required: --a'),
      exitCode: 2,
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      text: formatError(scriptPath, `unrecognized arguments: ${extras.join(' ')}`),
      exitCode: 2,
    };
  }

  return {
    kind: 'ok',
    args: {
      a: argumentValue,
    },
  };
}

